#pragma once

// miniz_export.h — normally generated by CMake's GenerateExportHeader when
// building miniz as a shared library. JPEGView compiles miniz statically
// into the exe (see JPEGView.vcxproj), so MINIZ_EXPORT is empty. This file
// is the exact equivalent of what miniz's CMakeLists.txt amalgamation step
// emits for a static build:
//   #ifndef MINIZ_EXPORT
//   #define MINIZ_EXPORT
//   #endif
// (upstream richgel999/miniz, master snapshot 2026-11-06; miniz_export.h
// itself is not shipped in the miniz repo — it is build-generated.)
#ifndef MINIZ_EXPORT
#define MINIZ_EXPORT
#endif
